import functools
import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        if maxsize <= 0:
            raise ValueError("maxsize must be positive")
        if ttl <= 0:
            raise ValueError("ttl must be positive")

        cache = {}
        last_accessed = {}

        def _update_cache(key, value, timestamp):
            if key in cache:
                del cache[key]
            cache[key] = value
            last_accessed[key] = timestamp

        def _check_ttl(key):
            if key in last_accessed:
                timestamp = last_accessed[key]
                if timestamp + ttl < timer():
                    del cache[key]
                    del last_accessed[key]

        def _get(key):
            _check_ttl(key)
            return cache.get(key)

        def _put(key, value):
            _check_ttl(key)
            _update_cache(key, value, timer())

        def _clear():
            cache.clear()
            last_accessed.clear()

        @functools.wraps(func)
        def memoize(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            _put(key, result)
            return result

        memoize.get = _get
        memoize.put = _put
        memoize.clear = _clear

        return memoize

    return decorator
