def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""

    # Check if the tag is not empty
    if not tag:
        return False

    # Check if the tag contains only alphanumeric characters
    if not tag.isalnum():
        return False

    # Check if the tag is not too long
    if len(tag) > 50:
        return False

    # Check if the tag is not too short
    if len(tag) < 3:
        return False

    # Check if the tag is not a reserved word
    if tag.lower() in ['owner', 'gdpr', 'admin']:
        return False

    return True
